package com.pp.shaderlod.optimization.photon;
import net.irisshaders.iris.targets.*;
import org.lwjgl.opengl.*;
import java.util.*;
/** Actual draw-bound observations after native sampler and framebuffer/viewport setup. */
public final class PhotonSpatialGl {
 public record Texture(int id,int width,int height,int format,int base,int compare,int min,int mag,int depthBits,int depthType){
  /** Existing sized-image callers retain their exact observations; untyped raw depth is refused. */
  public Texture(int id,int width,int height,int format,int base,int compare,int min,int mag){this(id,width,height,format,base,compare,min,mag,0,0);}
 }
 public record Proof(boolean valid,PhotonSpatialEpoch.Output output,Texture data,Texture depth){}
 private PhotonSpatialGl(){}
 private static int param(int sampler,int name){return sampler==0?GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,name):GL33.glGetSamplerParameteri(sampler,name);}
 private static Texture snapshot(int id,int sampler){
  int width=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_WIDTH),height=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_HEIGHT),format=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_INTERNAL_FORMAT);
  int depthBits=format==0x1902?GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,0x884A):0,depthType=format==0x1902?GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,0x8C16):0;
  return new Texture(id,width,height,format,GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL12.GL_TEXTURE_BASE_LEVEL),param(sampler,GL14.GL_TEXTURE_COMPARE_MODE),param(sampler,GL11.GL_TEXTURE_MIN_FILTER),param(sampler,GL11.GL_TEXTURE_MAG_FILTER),depthBits,depthType);
 }
 public static Texture binding(int program,String name){int location=GL20.glGetUniformLocation(program,name);if(location<0)return null;int unit=GL20.glGetUniformi(program,location);if(unit<0||unit>=GL11.glGetInteger(GL20.GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS))return null;int old=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);try{GL13.glActiveTexture(GL13.GL_TEXTURE0+unit);int id=GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D),sampler=GL11.glGetInteger(GL33.GL_SAMPLER_BINDING);return id<=0?null:snapshot(id,sampler);}finally{GL13.glActiveTexture(old);}}
 private static Texture image(int id){int old=GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D);try{GL11.glBindTexture(GL11.GL_TEXTURE_2D,id);return snapshot(id,0);}finally{GL11.glBindTexture(GL11.GL_TEXTURE_2D,old);}}
 private static boolean base(Texture t,int w,int h){return t!=null&&t.id()>0&&t.width()==w&&t.height()==h&&t.base()==0&&t.compare()==0&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(t.min())&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(t.mag());}
 private static boolean target(RenderTargets t,int logical,int texture,int format){var a=t.get(logical);return a!=null&&texture>0&&(texture==a.getMainTexture()||texture==a.getAltTexture())&&a.getWidth()==t.getCurrentWidth()&&a.getHeight()==t.getCurrentHeight()&&image(texture).format()==format;}
 private static int output(int slot){int attachment=GL11.glGetInteger(GL20.GL_DRAW_BUFFER0+slot);if(attachment<GL30.GL_COLOR_ATTACHMENT0||attachment>=GL30.GL_COLOR_ATTACHMENT0+GL11.glGetInteger(GL30.GL_MAX_COLOR_ATTACHMENTS))return 0;if(GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)!=GL11.GL_TEXTURE||GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)!=0)return 0;return GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,attachment,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);}
 private static boolean state(int program,int w,int h,boolean half){int[] viewport=new int[4],mask=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,viewport);GL11.glGetIntegerv(GL11.GL_COLOR_WRITEMASK,mask);return w>=2&&h>=2&&w<=8192&&h<=8192&&GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM)==program&&GL20.glGetProgrami(program,GL20.GL_LINK_STATUS)==GL11.GL_TRUE&&GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&Arrays.equals(viewport,new int[]{0,0,half?w/2:w,half?h/2:h})&&Arrays.equals(mask,new int[]{1,1,1,1})&&!GL11.glIsEnabled(GL11.GL_BLEND)&&!GL11.glIsEnabled(GL11.GL_DEPTH_TEST)&&!GL11.glIsEnabled(GL11.GL_STENCIL_TEST)&&!GL11.glIsEnabled(GL11.GL_SCISSOR_TEST)&&!GL11.glIsEnabled(GL30.GL_RASTERIZER_DISCARD);}
 public static int integer(int program,String name){int l=GL20.glGetUniformLocation(program,name);return l<0?-1:GL20.glGetUniformi(program,l);}
 public static void write(int program,String name,int value){int l=GL20.glGetUniformLocation(program,name);if(l>=0)GL20.glUniform1i(l,value);}
 private static boolean protocols(int p){int preset=integer(p,"shaderlodPreset");return integer(p,"shaderlodBridgeVersion")==2&&integer(p,"shaderlodEnabled")==1&&integer(p,"shaderlodOptimizationFlagsVersion")==1&&integer(p,"shaderlodEffectsVersion")==2&&preset>=0&&preset<=2;}
 /** Exact two observed depth handle forms: int in1.21.1, pinned Iris interface inlater tuples. */
 private static int depthId(Object depth){if(depth instanceof Integer i)return PhotonSpatialApiPins.gpuDepth()?-1:i;try{if(!PhotonSpatialApiPins.gpuDepth())return -1;var type=Class.forName("net.irisshaders.iris.mixinterface.GpuTextureInterface");return type.isInstance(depth)?(int)type.getMethod("iris$getGlId").invoke(depth):-1;}catch(ReflectiveOperationException unavailable){return -1;}}
 public static boolean inputImagesQualified(Texture data,Texture depth,int w,int h,int dataMain,int dataAlt,int nativeDepth){return base(data,w,h)&&data.format()==GL11.GL_RGBA16&&(data.id()==dataMain||data.id()==dataAlt)&&base(depth,w,h)&&com.pp.shaderlod.optimization.DepthTextureStorage.accepts(depth.format(),depth.depthBits(),depth.depthType())&&depth.id()==nativeDepth&&data.id()!=depth.id();}
 private static boolean inputs(RenderTargets targets,Texture data,Texture depth){var nativeData=targets.get(1);return nativeData!=null&&nativeData.getWidth()==targets.getCurrentWidth()&&nativeData.getHeight()==targets.getCurrentHeight()&&inputImagesQualified(data,depth,targets.getCurrentWidth(),targets.getCurrentHeight(),nativeData.getMainTexture(),nativeData.getAltTexture(),depthId(targets.getDepthTextureNoTranslucents()));}
 public static boolean sameInputs(Proof producer,Proof consumer){return producer!=null&&consumer!=null&&producer.valid()&&consumer.valid()&&Objects.equals(producer.data(),consumer.data())&&Objects.equals(producer.depth(),consumer.depth());}
 public static final List<String> FLOAT_CONTROLS=List.of("shaderlodNear","shaderlodFar","shaderlodTransition","shaderlodOpaqueLightingNear","shaderlodOpaqueLightingFar","shaderlodOpaqueLightingTransition","shaderlodOpaqueLightingMediumWorkRatio","shaderlodOpaqueLightingFarWorkRatio");
 public static Map<String,Integer> controls(int program){var m=new TreeMap<String,Integer>();for(String n:List.of("shaderlodBridgeVersion","shaderlodEnabled","shaderlodPreset","shaderlodOptimizationFlagsVersion","shaderlodEffectsVersion","shaderlodOpaqueLightingMode","shaderlodOptSpatialLightingReuse","shaderlodOptSpatialLightingRate","shaderlodCapabilitiesVersion"))m.put(n,integer(program,n));for(String n:FLOAT_CONTROLS){int l=GL20.glGetUniformLocation(program,n);m.put(n,l<0?Integer.MIN_VALUE:Float.floatToRawIntBits(GL20.glGetUniformf(program,l)));}return Map.copyOf(m);}
 public static Proof producer(RenderTargets targets,int p,boolean half){int w=targets.getCurrentWidth(),h=targets.getCurrentHeight(),cache=output(half?0:1),sky=half?0:output(0);var data=binding(p,"colortex1");var depth=binding(p,"depthtex1");boolean valid=state(p,w,h,half)&&protocols(p)&&(half||integer(p,"shaderlodCapabilitiesVersion")==1)&&target(targets,2,cache,half?GL30.GL_RGBA16F:GL30.GL_RGBA32F)&&inputs(targets,data,depth)&&data.id()!=cache&&(half||data.id()!=sky)&&depth.id()!=cache&&(half||depth.id()!=sky)&&(half||target(targets,0,sky,GL30.GL_R11F_G11F_B10F)&&sky!=cache)&&GL20.glGetUniformLocation(p,half?"shaderlodPhotonLightingResources":"shaderlodOpaqueSpatialAvailable")>=0;return new Proof(valid,new PhotonSpatialEpoch.Output(cache,sky,GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)),data,depth);}
 public static Proof consumer(RenderTargets targets,int p,boolean half){int w=targets.getCurrentWidth(),h=targets.getCurrentHeight();var cache=binding(p,"colortex2");var sky=half?null:binding(p,"colortex0");var data=binding(p,"colortex1");var depth=binding(p,"depthtex1");int color=output(0);boolean valid=state(p,w,h,false)&&protocols(p)&&(half||integer(p,"shaderlodCapabilitiesVersion")==1)&&target(targets,0,color,GL30.GL_R11F_G11F_B10F)&&base(cache,w,h)&&target(targets,2,cache.id(),half?GL30.GL_RGBA16F:GL30.GL_RGBA32F)&&color!=cache.id()&&inputs(targets,data,depth)&&data.id()!=color&&data.id()!=cache.id()&&depth.id()!=color&&depth.id()!=cache.id()&&(half||base(sky,w,h)&&data.id()!=sky.id()&&depth.id()!=sky.id()&&target(targets,0,sky.id(),GL30.GL_R11F_G11F_B10F)&&color!=sky.id());return new Proof(valid,new PhotonSpatialEpoch.Output(cache==null?0:cache.id(),sky==null?0:sky.id(),GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)),data,depth);}
}
